    // Silver customer is charged the reduced basket total
    public void S2_SilverCustomerIsChargedReducedTotal() =>
        Assert.Equal(9000, Charged(LoyaltyTier.Silver, 10000));

    [Fact]
    // Gold customer is charged the reduced basket total
    public void S3_GoldCustomerIsChargedReducedTotal() =>
        Assert.Equal(8500, Charged(LoyaltyTier.Gold, 10000));

    [Fact]
    // Bronze customer with a tiny basket is charged a whole cent amount
    public void S4_BronzeTinyBasketIsChargedWholeCents() =>
        Assert.Equal(7, Charged(LoyaltyTier.Bronze, 7));
}
